def normalize(text: str) -> str:
    """Make spelling variants match one form: nukta, chandrabindu and zero-width joiners differ between keyboards and say the same thing."""
    text = unicodedata.normalize('NFC', text or '')
    text = text.replace('\u093c', '').replace('\u0901', '\u0902').replace('\u200c', '').replace('\u200d', '')
    return text.lower()


