# Patterns go through the SAME normalisation as the text. Without this, any pattern containing a letter like ड़ (typed as one character) could never
# match the normalised text, and would silently miss real emergencies.
PATTERNS: List[Tuple[str, 're.Pattern']] = [(label, re.compile(normalize(rx))) for label, rx in _RAW]

# A negation that FOLLOWS the symptom, in the same clause: "सीने में दर्द नहीं है" (no chest pain). Deliberately narrow: when in doubt, alert.
# \b does not work after Devanagari/Kannada combining marks, so "not followed by another letter" is spelled out.
_NEGATION = re.compile(r'^\s*(?:है\s*)?(नहीं|नही|नाही|नव्हे|ಇಲ್ಲ|nahi|nahin|naahi|illa)(?![\u0900-\u097f\u0c80-\u0cffA-Za-z])')
_CLAUSE_BREAK = re.compile(r'[,;.!?।]|लेकिन|मगर|पर\s|और\s|पण\s|आणि|ಆದರೆ|ಮತ್ತು|\bbut\b|\band\b')


_WORD_REST = re.compile(r'[\u0900-\u097f\u0c80-\u0cffA-Za-z]*')


def _negated_after(text: str, end: int) -> bool:
    end += _WORD_REST.match(text, end).end() - end        # finish the word the match stopped inside (बेहोश|ी -> बेहोशी), then look for "not"
    tail = text[end:end + 16]
    brk = _CLAUSE_BREAK.search(tail)
    if brk:
        tail = tail[:brk.start()]
    return bool(_NEGATION.match(tail))


def detect(text: str) -> Tuple[List[str], bool]:
    """(English emergency labels found in hi/mr/kn text, whether self-harm wording was found). Safe on any input."""
    t = normalize(text)
    found: List[str] = []
    crisis = False
    for label, rx in PATTERNS:
        for m in rx.finditer(t):
            if _negated_after(t, m.end()):
                continue
            if label == 'Thoughts of self-harm':
                crisis = True
            elif label not in found:
                found.append(label)
            break
    return found, crisis
